'use strict';
const TOPICS = [
  {id:"sin",name:"Định lí sin",short:"ĐỊNH LÍ SIN",color:"#4385ff",soft:"#eaf2ff",desc:"Liên hệ cạnh và góc đối diện trong tam giác."},
  {id:"cos",name:"Định lí côsin",short:"CÔSIN",color:"#6d4aff",soft:"#f0edff",desc:"Tính cạnh, tính góc và vận dụng hệ thức côsin."},
  {id:"area",name:"Công thức tính diện tích tam giác",short:"DIỆN TÍCH",color:"#f29b35",soft:"#fff4e5",desc:"Tính diện tích, cạnh hoặc góc từ công thức diện tích."},
  {id:"solve",name:"Giải tam giác và ứng dụng thực tế",short:"GIẢI TAM GIÁC",color:"#19ad8c",soft:"#e6faf4",desc:"Tìm các yếu tố còn thiếu và giải bài toán thực tế."}
];
const STORAGE_KEY='vong_quay_tri_thuc_toan10_v2';
let studentCode='';
let database=loadDatabase();
let profile=null;
let wheelRotation=0;
let isSpinning=false;
let currentQuiz=null;
let lastResult=null;
let toastTimer=null;

function loadDatabase(){
  // Phục hồi an toàn nếu localStorage còn dữ liệu cũ hoặc dữ liệu bị hỏng.
  try {
    const raw=localStorage.getItem(STORAGE_KEY);
    const parsed=raw?JSON.parse(raw):null;
    if(!parsed||typeof parsed!=='object'||Array.isArray(parsed))return {profiles:{}};
    if(!parsed.profiles||typeof parsed.profiles!=='object'||Array.isArray(parsed.profiles))parsed.profiles={};
    return parsed;
  } catch(e) { return {profiles:{}}; }
}
function saveDatabase(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(database))}catch(e){showToast('Không lưu được tiến độ. Có thể trình duyệt đang chặn lưu trữ cục bộ.')}}
function freshProfile(code){const topics={};TOPICS.forEach(t=>topics[t.id]={answered:0,correct:0,wrong:0,sessions:0,lastAt:null});return {code,topics,history:[],createdAt:Date.now()}}
function ensureProfile(code){
  if(!database||typeof database!=='object'||Array.isArray(database))database={profiles:{}};
  if(!database.profiles||typeof database.profiles!=='object'||Array.isArray(database.profiles))database.profiles={};
  if(!database.profiles[code]||typeof database.profiles[code]!=='object')database.profiles[code]=freshProfile(code);
  const p=database.profiles[code];
  if(!p.topics||typeof p.topics!=='object'||Array.isArray(p.topics))p.topics={};
  TOPICS.forEach(t=>{if(!p.topics[t.id]||typeof p.topics[t.id]!=='object')p.topics[t.id]={answered:0,correct:0,wrong:0,sessions:0,lastAt:null};['answered','correct','wrong','sessions'].forEach(k=>{if(!Number.isFinite(Number(p.topics[t.id][k])))p.topics[t.id][k]=0});if(!('lastAt' in p.topics[t.id]))p.topics[t.id].lastAt=null});
  if(!Array.isArray(p.history))p.history=[];
  return p;
}
function topicById(id){return TOPICS.find(t=>t.id===id)||TOPICS[0]}
function fmt(n,d=1){if(!Number.isFinite(Number(n)))return '—';let v=Number(Number(n).toFixed(d));if(Object.is(v,-0))v=0;return v.toLocaleString('vi-VN',{maximumFractionDigits:d,minimumFractionDigits:0})}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function showToast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.add('hidden'),3000)}
function showScreen(id){['dashboardView','quizView','resultView'].forEach(s=>document.getElementById(s).classList.toggle('hidden',s!==id))}
function enterApp(code){studentCode=code;profile=ensureProfile(code);saveDatabase();document.getElementById('loginScreen').classList.add('hidden');document.getElementById('mainApp').classList.remove('hidden');document.getElementById('codeChip').textContent='Mã HS: '+code;drawWheel();renderDashboard();showScreen('dashboardView')}
function loginWithStudentCode(){
  const field=document.getElementById('studentCode');
  const error=document.getElementById('loginError');
  const code=field.value.replace(/\D/g,'').slice(0,6);
  field.value=code;
  if(!/^\d{6}$/.test(code)){
    error.textContent='Mã học sinh phải gồm đúng 6 chữ số. Ví dụ: 123456.';
    field.focus();
    return;
  }
  try {
    error.textContent='';
    enterApp(code);
  } catch(err) {
    console.error('Không thể mở vòng quay:',err);
    document.getElementById('loginScreen').classList.remove('hidden');
    document.getElementById('mainApp').classList.add('hidden');
    error.textContent='Chưa mở được vòng quay ('+(err&&err.message?err.message:'lỗi không xác định')+'). Hãy tải lại trang và thử lại bằng Chrome hoặc Edge.';
  }
}
// Nhập mã ổn định trên Safari iPhone: chỉ giữ chữ số, tối đa 6 ký tự.
document.getElementById('studentCode').addEventListener('input',function(e){
  const cleaned=String(e.target.value||'').replace(/[^0-9]/g,'').slice(0,6);
  if(e.target.value!==cleaned)e.target.value=cleaned;
  document.getElementById('loginError').textContent='';
});
// Chỉ dùng MỘT luồng submit để tránh xử lý click/submit hai lần trên iOS.
const loginForm=document.getElementById('loginForm');
loginForm.addEventListener('submit',function(e){
  e.preventDefault();
  e.stopPropagation();
  loginWithStudentCode();
});
document.getElementById('studentCode').addEventListener('keydown',function(e){
  if(e.key==='Enter'){
    e.preventDefault();
    loginWithStudentCode();
  }
});
document.getElementById('changeStudentBtn').addEventListener('click',()=>{document.getElementById('mainApp').classList.add('hidden');document.getElementById('loginScreen').classList.remove('hidden');document.getElementById('studentCode').value='';document.getElementById('studentCode').focus()});

function drawWheel(){const canvas=document.getElementById('wheelCanvas');const ctx=canvas.getContext('2d');const size=canvas.width,center=size/2,radius=size/2-7;ctx.clearRect(0,0,size,size);const colors=TOPICS.map(t=>t.color);TOPICS.forEach((topic,i)=>{const start=-Math.PI/2+i*Math.PI/2,end=start+Math.PI/2;ctx.beginPath();ctx.moveTo(center,center);ctx.arc(center,center,radius,start,end);ctx.closePath();ctx.fillStyle=colors[i];ctx.fill();ctx.lineWidth=8;ctx.strokeStyle='#ffffff';ctx.stroke();const mid=start+Math.PI/4;ctx.save();ctx.translate(center+Math.cos(mid)*radius*.65,center+Math.sin(mid)*radius*.65);let angle=mid;if(mid>Math.PI/2&&mid<Math.PI*1.5)angle+=Math.PI;ctx.rotate(angle);ctx.fillStyle='#fff';ctx.textAlign='center';ctx.textBaseline='middle';ctx.font='800 25px system-ui, sans-serif';const lines=topic.id==='solve'?['GIẢI TAM GIÁC','& ỨNG DỤNG']:topic.id==='area'?['DIỆN TÍCH','TAM GIÁC']:topic.id==='cos'?['ĐỊNH LÍ','CÔSIN']:['ĐỊNH LÍ SIN'];lines.forEach((line,j)=>ctx.fillText(line,0,(j-(lines.length-1)/2)*31));ctx.restore()});ctx.beginPath();ctx.arc(center,center,radius,0,Math.PI*2);ctx.lineWidth=7;ctx.strokeStyle='#fff';ctx.stroke()}
function daysSince(ts){if(!ts)return 7;return Math.max(0,(Date.now()-ts)/86400000)}
function topicWeight(topicId){const s=profile.topics[topicId];const total=s.correct+s.wrong;const errorRate=total?s.wrong/total:0;const elapsed=Math.min(daysSince(s.lastAt)/7,1);return .05+.7*errorRate+.3*elapsed}
function chooseTopicWeighted(){const weights=TOPICS.map(t=>topicWeight(t.id));const total=weights.reduce((a,b)=>a+b,0);let r=Math.random()*total;for(let i=0;i<TOPICS.length;i++){r-=weights[i];if(r<=0)return TOPICS[i]}return TOPICS[TOPICS.length-1]}
document.getElementById('spinBtn').addEventListener('click',()=>{if(isSpinning)return;isSpinning=true;const btn=document.getElementById('spinBtn');btn.disabled=true;const chosen=chooseTopicWeighted();const index=TOPICS.findIndex(t=>t.id===chosen.id);const target=((315-index*90)%360+360)%360;const current=((wheelRotation%360)+360)%360;const delta=(target-current+360)%360;wheelRotation+=360*(5+Math.floor(Math.random()*3))+delta;const canvas=document.getElementById('wheelCanvas');document.getElementById('wheelStatus').textContent='Vòng quay đang chọn chủ đề…';canvas.style.transform=`rotate(${wheelRotation}deg)`;let finished=false;const finishSpin=()=>{if(finished)return;finished=true;isSpinning=false;btn.disabled=false;document.getElementById('wheelStatus').textContent='Chủ đề được chọn: '+chosen.name;startQuiz(chosen.id)};canvas.addEventListener('transitionend',function handler(){canvas.removeEventListener('transitionend',handler);setTimeout(finishSpin,350)},{once:true});setTimeout(finishSpin,5700)});

function renderDashboard(){if(!profile)return;let totalCorrect=0,totalAnswered=0,totalSessions=profile.history.length;TOPICS.forEach(t=>{totalCorrect+=profile.topics[t.id].correct;totalAnswered+=profile.topics[t.id].correct+profile.topics[t.id].wrong});document.getElementById('statAnswered').textContent=totalAnswered;document.getElementById('statAccuracy').textContent=totalAnswered?fmt(totalCorrect/totalAnswered*100,1)+'%':'—';document.getElementById('statSessions').textContent=totalSessions;const tried=TOPICS.filter(t=>(profile.topics[t.id].correct+profile.topics[t.id].wrong)>0);let weakest=null;if(tried.length){weakest=tried.slice().sort((a,b)=>rate(b.id)-rate(a.id))[0];document.getElementById('statWeak').textContent=weakest.name.length>15?weakest.name.slice(0,14)+'…':weakest.name;document.getElementById('recommendTitle').textContent='Ưu tiên ôn: '+weakest.name;document.getElementById('recommendText').textContent=`Bạn đã sai ${profile.topics[weakest.id].wrong}/${profile.topics[weakest.id].correct+profile.topics[weakest.id].wrong} câu ở phần này. Vòng quay sẽ ưu tiên nhẹ chủ đề này trong các lượt tiếp theo.`}else{document.getElementById('statWeak').textContent='Chưa có';document.getElementById('recommendTitle').textContent='Gợi ý ôn tập';document.getElementById('recommendText').textContent='Hãy hoàn thành lượt đầu tiên để hệ thống nhận diện dạng bài cần củng cố.'}const list=document.getElementById('topicList');list.innerHTML='';TOPICS.forEach((t,i)=>{const s=profile.topics[t.id],n=s.correct+s.wrong,pct=n?s.correct/n*100:0;const card=document.createElement('div');card.className='topic-card';card.style.setProperty('--topic-color',t.color);card.innerHTML=`<div class="topic-number">CHỦ ĐỀ 0${i+1}</div><div class="topic-name">${escapeHtml(t.name)}</div><div class="topic-meta"><span>${n} câu đã làm</span><strong>${n?fmt(pct,0)+'% đúng':'Chưa có dữ liệu'}</strong></div><div class="progress"><span style="width:${pct}%;background:${t.color}"></span></div>`;list.appendChild(card)});renderHistory()}
function renderHistory(){const chart=document.getElementById('progressChart');const ctx=chart.getContext('2d');const rows=(profile.history||[]).slice(0,8).reverse();document.getElementById('historyCount').textContent=(profile.history||[]).length+' lượt';ctx.clearRect(0,0,chart.width,chart.height);const W=chart.width,H=chart.height,L=48,R=22,T=20,B=62,plotW=W-L-R,plotH=H-T-B;ctx.font='13px system-ui,sans-serif';ctx.textBaseline='middle';[0,2.5,5,7.5,10].forEach(v=>{const y=T+plotH-(v/10)*plotH;ctx.beginPath();ctx.moveTo(L,y);ctx.lineTo(W-R,y);ctx.strokeStyle='#eeecf7';ctx.lineWidth=1;ctx.stroke();ctx.fillStyle='#9691aa';ctx.textAlign='right';ctx.fillText(String(v).replace('.',','),L-10,y)});if(!rows.length){ctx.textAlign='center';ctx.fillStyle='#9993ae';ctx.font='15px system-ui,sans-serif';ctx.fillText('Nộp bài lần đầu để bắt đầu theo dõi tiến trình',W/2,H/2);document.getElementById('historyList').innerHTML='<div class="muted small">Chưa có lượt làm bài được lưu.</div>';return}const points=rows.map((r,i)=>({x:rows.length===1?L+plotW/2:L+i*(plotW/(rows.length-1)),y:T+plotH-(Math.max(0,Math.min(10,r.score))/10)*plotH,r}));ctx.beginPath();points.forEach((p,i)=>i===0?ctx.moveTo(p.x,p.y):ctx.lineTo(p.x,p.y));ctx.strokeStyle='#6d4aff';ctx.lineWidth=3;ctx.lineJoin='round';ctx.stroke();points.forEach(p=>{ctx.beginPath();ctx.arc(p.x,p.y,5.5,0,Math.PI*2);ctx.fillStyle='#6d4aff';ctx.fill();ctx.lineWidth=2.5;ctx.strokeStyle='#fff';ctx.stroke();ctx.fillStyle='#44347a';ctx.font='800 13px system-ui,sans-serif';ctx.textAlign='center';ctx.fillText(fmt(p.r.score,1),p.x,Math.max(T+9,p.y-15));const d=new Date(p.r.at);const date=d.toLocaleDateString('vi-VN',{day:'2-digit',month:'2-digit'});const short=p.r.topicId==='cos'?'Côsin':p.r.topicId==='sin'?'Sin':p.r.topicId==='area'?'Diện tích':'Ứng dụng';ctx.fillStyle='#847f9b';ctx.font='11px system-ui,sans-serif';ctx.fillText(date,p.x,H-39);ctx.fillText(short,p.x,H-22)});const list=document.getElementById('historyList');list.innerHTML='';(profile.history||[]).slice(0,5).forEach(r=>{const d=new Date(r.at);const when=d.toLocaleDateString('vi-VN',{day:'2-digit',month:'2-digit',year:'numeric'})+' · '+d.toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit'});const row=document.createElement('div');row.className='history-row';row.innerHTML=`<div class="history-row-main"><strong>${escapeHtml(r.topicName)} ${r.mode==='retry'?'· Luyện lại':''}</strong><span>${escapeHtml(when)} · ${r.correct}/${r.total} câu đúng</span></div><span class="history-score">${fmt(r.score,1)}/10</span>`;list.appendChild(row)})}
function rate(id){const s=profile.topics[id],n=s.correct+s.wrong;return n?s.wrong/n:0}

function makeOptions(correct,unit,digits=1){const rounded=Number(Number(correct).toFixed(digits));const label=v=>`${fmt(v,digits)}${unit}`;const answerText=label(rounded);let vals=[];const offsets=unit==='°'?[5,-5,10,-10,15,-15,20,-20,30,-30,7,-7]:[1,-1,2,-2,3,-3,.5,-.5,4,-4,5,-5,1.5,-1.5];for(const off of offsets){let v=rounded+off;if(unit==='°')v=Math.max(1,Math.min(179,v));else v=Math.max(.1,v);const text=label(v);if(text!==answerText&&!vals.includes(text))vals.push(text);if(vals.length===3)break}let mult=1;while(vals.length<3){let v=unit==='°'?Math.max(1,Math.min(179,rounded+mult*11)):Math.max(.1,rounded+mult*6.5);let text=label(v);if(text!==answerText&&!vals.includes(text))vals.push(text);mult++}const all=[answerText,...vals];for(let i=all.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[all[i],all[j]]=[all[j],all[i]]}return {options:all,answerText}}
function buildQuestion(topicId,kind,p,serial=1){let prompt='',explanation='',correct=0,unit='',digits=1,label='Vận dụng';
 if(kind==='cos_side'||kind==='solve_cos_side'||kind==='app_cos'){
  const {a,b,C}=p;correct=Math.sqrt(Math.max(0,a*a+b*b-2*a*b*Math.cos(C*Math.PI/180)));unit=p.unit||' cm';digits=1;
  if(kind==='app_cos') {prompt=`Từ điểm O, hai người đi theo hai hướng OA = ${fmt(a,1)} km và OB = ${fmt(b,1)} km, hai hướng tạo với nhau góc ${fmt(C,0)}°. Khoảng cách thẳng AB xấp xỉ bao nhiêu?`;unit=' km';label='Ứng dụng thực tế';explanation=`Áp dụng định lí côsin: AB² = OA² + OB² − 2·OA·OB·cos(O) = ${fmt(a,1)}² + ${fmt(b,1)}² − 2·${fmt(a,1)}·${fmt(b,1)}·cos ${fmt(C,0)}°. Suy ra AB ≈ ${fmt(correct,1)} km.`;
  }else{prompt=`Cho tam giác ABC có a = ${fmt(a,1)} cm, b = ${fmt(b,1)} cm và góc C = ${fmt(C,0)}°. Tính cạnh c (đối diện góc C).`;label=kind==='solve_cos_side'?'Giải tam giác':'Tính cạnh';explanation=`Theo định lí côsin: c² = a² + b² − 2ab·cos C = ${fmt(a,1)}² + ${fmt(b,1)}² − 2·${fmt(a,1)}·${fmt(b,1)}·cos ${fmt(C,0)}°. Vậy c ≈ ${fmt(correct,1)} cm.`}
 }else if(kind==='cos_angle'){
  const {a,b,c}=p;const cosC=(a*a+b*b-c*c)/(2*a*b);correct=Math.acos(Math.max(-1,Math.min(1,cosC)))*180/Math.PI;unit='°';digits=1;label='Tính góc';prompt=`Trong tam giác ABC, a = ${fmt(a,0)} cm, b = ${fmt(b,0)} cm, c = ${fmt(c,0)} cm. Góc C xấp xỉ bằng bao nhiêu?`;explanation=`Theo định lí côsin: cos C = (a² + b² − c²)/(2ab) = (${a}² + ${b}² − ${c}²)/(2·${a}·${b}). Do đó C ≈ ${fmt(correct,1)}°.`;
 }else if(kind==='sin_find_side'){
  const {a,A,B}=p;correct=a*Math.sin(B*Math.PI/180)/Math.sin(A*Math.PI/180);unit=' cm';digits=1;label='Tìm cạnh';prompt=`Cho tam giác ABC có a = ${fmt(a,0)} cm, A = ${fmt(A,0)}°, B = ${fmt(B,0)}°. Tính cạnh b đối diện góc B.`;explanation=`Định lí sin: a/sin A = b/sin B. Suy ra b = a·sin B/sin A = ${fmt(a,0)}·sin ${B}°/sin ${A}° ≈ ${fmt(correct,1)} cm.`;
 }else if(kind==='sin_find_angle'){
  const {a,A,b}=p;const ratio=Math.max(0,Math.min(1,b*Math.sin(A*Math.PI/180)/a));correct=Math.asin(ratio)*180/Math.PI;unit='°';digits=1;label='Tìm góc';prompt=`Cho tam giác ABC có a = ${fmt(a,0)} cm, A = ${fmt(A,0)}°, b = ${fmt(b,0)} cm. Biết góc B là góc nhọn. Góc B bằng khoảng bao nhiêu?`;explanation=`Từ định lí sin: sin B = b·sin A/a = ${fmt(b,0)}·sin ${A}°/${fmt(a,0)}. Vì B là góc nhọn nên B = arcsin(${fmt(ratio,3)}) ≈ ${fmt(correct,1)}°.`;
 }else if(kind==='sin_find_side2'){
  const {c,C,A}=p;correct=c*Math.sin(A*Math.PI/180)/Math.sin(C*Math.PI/180);unit=' cm';digits=1;label='Tìm cạnh';prompt=`Cho tam giác ABC có c = ${fmt(c,0)} cm, C = ${fmt(C,0)}°, A = ${fmt(A,0)}°. Tính cạnh a đối diện góc A.`;explanation=`Theo định lí sin: a/sin A = c/sin C nên a = c·sin A/sin C = ${fmt(c,0)}·sin ${A}°/sin ${C}° ≈ ${fmt(correct,1)} cm.`;
 }else if(kind==='area_find'){
  const {a,b,C}=p;correct=.5*a*b*Math.sin(C*Math.PI/180);unit=' cm²';digits=1;label='Tính diện tích';prompt=`Tam giác ABC có hai cạnh a = ${fmt(a,0)} cm, b = ${fmt(b,0)} cm và góc xen giữa C = ${fmt(C,0)}°. Diện tích tam giác bằng bao nhiêu?`;explanation=`Dùng công thức S = ½ab·sin C = ½·${fmt(a,0)}·${fmt(b,0)}·sin ${fmt(C,0)}° ≈ ${fmt(correct,1)} cm².`;
 }else if(kind==='area_solve_side'){
  const {a,b,C}=p;const areaRaw=.5*a*b*Math.sin(C*Math.PI/180);const areaShown=Number(areaRaw.toFixed(2));correct=2*areaShown/(b*Math.sin(C*Math.PI/180));unit=' cm';digits=1;label='Tìm cạnh';prompt=`Tam giác có diện tích S = ${fmt(areaShown,2)} cm², cạnh b = ${fmt(b,0)} cm và góc xen giữa hai cạnh a, b là C = ${fmt(C,0)}°. Tìm cạnh a.`;explanation=`Từ S = ½ab·sin C, suy ra a = 2S/(b·sin C) = 2·${fmt(areaShown,2)}/(${fmt(b,0)}·sin ${fmt(C,0)}°) ≈ ${fmt(correct,1)} cm.`;
 }else if(kind==='area_find_angle'){
  const {a,b,C}=p;const areaRaw=.5*a*b*Math.sin(C*Math.PI/180);const areaShown=Number(areaRaw.toFixed(2));const ratio=Math.max(0,Math.min(1,2*areaShown/(a*b)));correct=Math.asin(ratio)*180/Math.PI;unit='°';digits=1;label='Tìm góc';prompt=`Tam giác có diện tích S = ${fmt(areaShown,2)} cm², hai cạnh a = ${fmt(a,0)} cm, b = ${fmt(b,0)} cm. Biết góc C không vượt quá 90°. Tính C.`;explanation=`S = ½ab·sin C nên sin C = 2S/(ab) = 2·${fmt(areaShown,2)}/(${fmt(a,0)}·${fmt(b,0)}). Vì C không tù (C ≤ 90° theo điều kiện bài), C = arcsin(${fmt(ratio,3)}) ≈ ${fmt(correct,1)}°.`;
 }else if(kind==='sum_angles'){
  const {A,B}=p;correct=180-A-B;unit='°';digits=0;label='Tổng ba góc';prompt=`Trong tam giác ABC, A = ${fmt(A,0)}° và B = ${fmt(B,0)}°. Số đo góc C là bao nhiêu?`;explanation=`Tổng ba góc trong một tam giác bằng 180°. Vậy C = 180° − ${fmt(A,0)}° − ${fmt(B,0)}° = ${fmt(correct,0)}°.`;
 }
 const generated=makeOptions(correct,unit,digits);return {id:`${topicId}_${kind}_${serial}_${Math.random().toString(36).slice(2,7)}`,topicId,kind,p:{...p},serial,prompt,explanation,correctValue:correct,unit,digits,label,options:generated.options,answerText:generated.answerText};
}

// Ngân hàng 120 câu hỏi lấy trực tiếp từ tài liệu Word: 4 phần, mỗi phần 30 câu.
const QUESTION_BANK = [{"num":1,"topicId":"sin","prompt":"Cho tam giác ABC có các cạnh BC = a, CA = b, AB = c và bán kính đường tròn ngoại tiếp là R. Hệ thức nào sau đây đúng?","options":["a/sin A = b/sin B = c/sin C = R","a/sin A = b/sin B = c/sin C = 2R","sin A/a = sin B/b = sin C/c = 2R","a·sin A = b·sin B = c·sin C = 2R"],"answerText":"a/sin A = b/sin B = c/sin C = 2R","explanation":"Định lí sin khẳng định tỉ số giữa một cạnh và sin góc đối diện bằng đường kính 2R của đường tròn ngoại tiếp.","label":"Câu hỏi 1"},{"num":2,"topicId":"sin","prompt":"Cho tam giác ABC có sin A = 1/2 và cạnh a = 6. Tính bán kính R của đường tròn ngoại tiếp tam giác ABC.","options":["R = 3","R = 6","R = 12","R = 4"],"answerText":"R = 6","explanation":"R = a / (2·sin A) = 6 / (2 · 1/2) = 6.","label":"Câu hỏi 2"},{"num":3,"topicId":"sin","prompt":"Cho tam giác ABC nội tiếp đường tròn bán kính R = 5. Tính cạnh a biết góc A = 30°.","options":["a = 5","a = 10","a = 2.5","a = 5√3"],"answerText":"a = 5","explanation":"a = 2R·sin A = 2 · 5 · sin 30° = 5.","label":"Câu hỏi 3"},{"num":4,"topicId":"sin","prompt":"Cho tam giác ABC có R là bán kính đường tròn ngoại tiếp. Giá trị của biểu thức P = a/sin A + b/sin B + c/sin C bằng:","options":["R","2R","4R","6R"],"answerText":"6R","explanation":"Mỗi tỉ số a/sin A, b/sin B, c/sin C đều bằng 2R. Do đó tổng bằng 2R + 2R + 2R = 6R.","label":"Câu hỏi 4"},{"num":5,"topicId":"sin","prompt":"Cho tam giác ABC có cạnh a = 5√3 và bán kính đường tròn ngoại tiếp R = 5. Tính góc A (biết góc A nhọn).","options":["30°","45°","60°","90°"],"answerText":"60°","explanation":"sin A = a / (2R) = 5√3 / 10 = √3/2 => góc A = 60°.","label":"Câu hỏi 5"},{"num":6,"topicId":"sin","prompt":"Công thức tính diện tích S của tam giác ABC nào sau đây đúng?","options":["S = 1/2·b·c·sin A","S = b·c·sin A","S = 1/2·b·c·cos A","S = a·b·c / (2R)"],"answerText":"S = 1/2·b·c·sin A","explanation":"Công thức diện tích tam giác theo hai cạnh và góc kẹp giữa: S = 1/2·b·c·sin A.","label":"Câu hỏi 6"},{"num":7,"topicId":"sin","prompt":"Cho tam giác ABC có a/sin A = 12. Đường kính D của đường tròn ngoại tiếp tam giác ABC là:","options":["6","12","24","18"],"answerText":"12","explanation":"Đường kính D = 2R = a/sin A = 12.","label":"Câu hỏi 7"},{"num":8,"topicId":"sin","prompt":"Trong tam giác ABC, hệ thức nào sau đây SAI?","options":["a = 2R·sin A","sin A = a/(2R)","b = 2R·sin C","sin C = c/(2R)"],"answerText":"b = 2R·sin C","explanation":"Hệ thức đúng phải là b = 2R·sin B.","label":"Câu hỏi 8"},{"num":9,"topicId":"sin","prompt":"Cho tam giác ABC có b = 8, góc B = 45°, góc C = 60°. Tính cạnh c.","options":["c = 4√2","c = 4√6","c = 2√6","c = 8√3"],"answerText":"c = 4√6","explanation":"c = b·sin C / sin B = 8 · sin 60° / sin 45° = 8 · (√3/2) / (√2/2) = 4√6.","label":"Câu hỏi 9"},{"num":10,"topicId":"sin","prompt":"Cho tam giác ABC có góc A = 135° và cạnh a = 10√2. Tính bán kính R.","options":["R = 5","R = 10","R = 5√2","R = 20"],"answerText":"R = 10","explanation":"R = a / (2·sin A) = 10√2 / (2 · sin 135°) = 10√2 / (2 · √2/2) = 10.","label":"Câu hỏi 10"},{"num":11,"topicId":"sin","prompt":"Cho tam giác ABC có góc A = 45°, góc B = 75° và cạnh c = 2√6. Tính độ dài cạnh a.","options":["2√6","4√2","2√2","4"],"answerText":"4√2","explanation":"Góc C = 180° - (45° + 75°) = 60°. Ta có a = c·sin A / sin C = 2√6 · sin 45° / sin 60° = 4√2.","label":"Câu hỏi 11"},{"num":12,"topicId":"sin","prompt":"Cho tam giác ABC thỏa mãn a/sin B = b/sin A. Tam giác ABC là tam giác gì?","options":["Tam giác đều","Tam giác vuông","Tam giác cân tại C","Tam giác vuông cân"],"answerText":"Tam giác cân tại C","explanation":"Vì a/sin A = b/sin B, kết hợp với giả thiết suy ra sin2 A = sin2 B => góc A = góc B => tam giác cân tại C.","label":"Câu hỏi 12"},{"num":13,"topicId":"sin","prompt":"Cho tam giác ABC có độ dài ba cạnh là a, b, c và bán kính đường tròn ngoại tiếp R. Công thức tính diện tích S đúng là:","options":["S = abc / R","S = abc / (4R)","S = 4Rabc","S = 4R / abc"],"answerText":"S = abc / (4R)","explanation":"Công thức diện tích tam giác qua 3 cạnh và bán kính ngoại tiếp: S = abc / (4R).","label":"Câu hỏi 13"},{"num":14,"topicId":"sin","prompt":"Cho tam giác ABC có chu vi bằng 24 và bán kính đường tròn ngoại tiếp R = 4. Tính P = sin A + sin B + sin C.","options":["P = 2","P = 3","P = 4","P = 6"],"answerText":"P = 3","explanation":"sin A + sin B + sin C = a/(2R) + b/(2R) + c/(2R) = (a+b+c)/(2R) = 24 / 8 = 3.","label":"Câu hỏi 14"},{"num":15,"topicId":"sin","prompt":"Cho tam giác ABC có a = 2, b = 2√3, c = 4. Tính góc A.","options":["30°","60°","45°","90°"],"answerText":"30°","explanation":"Nhận thấy a2 + b2 = 4 + 12 = 16 = c2 nên tam giác vuông tại C. Khi đó sin A = a/c = 2/4 = 1/2 => A = 30°.","label":"Câu hỏi 15"},{"num":16,"topicId":"sin","prompt":"Cho tam giác ABC có a = 8, góc A = 60°. Tính độ dài cạnh b biết sin B = √3/4.","options":["b = 4","b = 6","b = 8","b = 3"],"answerText":"b = 4","explanation":"b = a·sin B / sin A = 8 · (√3/4) / (√3/2) = 4.","label":"Câu hỏi 16"},{"num":17,"topicId":"sin","prompt":"Cho tam giác ABC có b = 7, c = 5, góc A = 60°. Diện tích tam giác ABC là:","options":["35√3/4","35√3/2","35/2","35√3"],"answerText":"35√3/4","explanation":"S = 1/2·b·c·sin A = 1/2 · 7 · 5 · sin 60° = 35√3/4.","label":"Câu hỏi 17"},{"num":18,"topicId":"sin","prompt":"Cho tam giác ABC thỏa mãn a = 2b·cos C. Khẳng định nào đúng về tam giác ABC?","options":["Tam giác đều","Tam giác cân tại A","Tam giác vuông","Tam giác cân tại B"],"answerText":"Tam giác cân tại A","explanation":"Thay a = 2R·sin A, b = 2R·sin B => sin A = 2·sin B·cos C. Mà sin A = sin(B+C) = sin B cos C + cos B sin C => sin(B - C) = 0 => B = C => cân tại A.","label":"Câu hỏi 18"},{"num":19,"topicId":"sin","prompt":"Trong tam giác ABC, nếu góc A > góc B thì khẳng định nào sau đây đúng về các cạnh đối diện?","options":["a > b","a < b","a = b","a >= b"],"answerText":"a > b","explanation":"Trong một tam giác, góc lớn hơn đối diện với cạnh lớn hơn, tức A > B <=> a > b.","label":"Câu hỏi 19"},{"num":20,"topicId":"sin","prompt":"Cho tam giác ABC có S = 10√3, ba cạnh a = 7, b = 8, c = 5. Tính bán kính R của đường tròn ngoại tiếp.","options":["R = 7/√3","R = 14/√3","R = 7","R = 5"],"answerText":"R = 7/√3","explanation":"R = abc / (4S) = (7 · 8 · 5) / (4 · 10√3) = 280 / (40√3) = 7/√3.","label":"Câu hỏi 20"},{"num":21,"topicId":"sin","prompt":"Cho tam giác ABC thỏa mãn b + c = 2a. Khẳng định nào đúng về các góc?","options":["sin B + sin C = 2·sin A","sin B + sin C = sin A","sin B + sin C = 3·sin A","sin B + sin C = 1/2·sin A"],"answerText":"sin B + sin C = 2·sin A","explanation":"Thay b = 2R·sin B, c = 2R·sin C, a = 2R·sin A vào giả thiết suy ra sin B + sin C = 2·sin A.","label":"Câu hỏi 21"},{"num":22,"topicId":"sin","prompt":"Cho tam giác ABC có sin A / 1 = sin B / √3 = sin C / 2. Tam giác ABC là tam giác gì?","options":["Tam giác đều","Tam giác vuông tại C","Tam giác vuông tại A","Tam giác cân"],"answerText":"Tam giác vuông tại C","explanation":"Tỉ lệ sin cũng là tỉ lệ cạnh: a : b : c = 1 : √3 : 2. Vì 12 + (√3)2 = 22 nên tam giác vuông tại C.","label":"Câu hỏi 22"},{"num":23,"topicId":"sin","prompt":"Cho tam giác ABC nội tiếp đường tròn (O; R). Biết a2 + b2 + c2 = 8R2. Khẳng định nào sau đây đúng?","options":["Tam giác nhọn","Tam giác vuông","Tam giác tù","Tam giác đều"],"answerText":"Tam giác vuông","explanation":"Thay a = 2R·sin A... ta có sin2 A + sin2 B + sin2 C = 2, đây là tính chất đặc trưng của tam giác vuông.","label":"Câu hỏi 23"},{"num":24,"topicId":"sin","prompt":"Cho tam giác ABC có a2 = b2 + c2 - bc. Khẳng định nào sau đây chính xác?","options":["Góc A = 60°","Góc A = 120°","Góc A = 45°","Góc A = 30°"],"answerText":"Góc A = 60°","explanation":"Theo định lí cosin a2 = b2 + c2 - 2bc·cos A => 2·cos A = 1 => cos A = 1/2 => góc A = 60°.","label":"Câu hỏi 24"},{"num":25,"topicId":"sin","prompt":"Cho tam giác ABC có sin A + sin B = cos A + cos B. Tam giác ABC là tam giác gì?","options":["Tam giác cân","Tam giác vuông","Tam giác vuông cân","Tam giác đều"],"answerText":"Tam giác vuông","explanation":"Biến đổi lượng giác đưa về sin((A+B)/2)·cos((A-B)/2) = cos((A+B)/2)·cos((A-B)/2) => góc C = 90°.","label":"Câu hỏi 25"},{"num":26,"topicId":"sin","prompt":"Để đo khoảng cách giữa 2 điểm A, B ở hai bên hồ, Nam chọn điểm C sao cho AC = 100m, góc CAB = 60°, góc ACB = 45°. Tính AB.","options":["73 m","90 m","122 m","141 m"],"answerText":"90 m","explanation":"Góc B = 180° - (60° + 45°) = 75°. AB = AC · sin 45° / sin 75° = 100 · 0.7071 / 0.9659 ≈ 89.66 m ≈ 90 m.","label":"Câu hỏi 26"},{"num":27,"topicId":"sin","prompt":"Một máy bay bay từ M đến N. Tại K trên mặt đất đo được góc nâng tới M là 30°, tới N là 75°. Biết MN = 10 km. Tính KN.","options":["5 km","5√2 km","10 km","5√3 km"],"answerText":"5√2 km","explanation":"Xét tam giác MKN có góc MKN = 75°, góc M = 30°. KN = MN · sin 30° / sin 75° ≈ 5.18 km (~ 5√2 km tuỳ góc).","label":"Câu hỏi 27"},{"num":28,"topicId":"sin","prompt":"Tàu thủy nhìn đỉnh hải đăng dưới góc 30°. Tiến lại gần 50m góc nâng thành 60°. Chiều cao ngọn hải đăng là:","options":["25√3 m","50 m","25 m","50√3 m"],"answerText":"25√3 m","explanation":"Gọi h là chiều cao. Distance1 = h·cot 30°, Distance2 = h·cot 60°. h(cot 30° - cot 60°) = 50 => h = 25√3 m.","label":"Câu hỏi 28"},{"num":29,"topicId":"sin","prompt":"Từ đỉnh tháp cao 60m nhìn 2 chiếc thuyền dưới góc hạ 30° và 45° (thẳng hàng). Khoảng cách 2 thuyền là:","options":["60(√3 - 1) m","60√3 m","60 m","30(√3 + 1) m"],"answerText":"60(√3 - 1) m","explanation":"d = 60·cot 30° - 60·cot 45° = 60√3 - 60 = 60(√3 - 1) m.","label":"Câu hỏi 29"},{"num":30,"topicId":"sin","prompt":"Hai tàu xuất phát từ cảng A đi theo 2 hướng tạo góc 60° với vận tốc 30 km/h và 40 km/h. Sau 2 giờ khoảng cách 2 tàu là:","options":["20√13 km","40√3 km","50 km","70 km"],"answerText":"20√13 km","explanation":"Quãng đường: s1 = 60km, s2 = 80km. Khoảng cách d2 = 602 + 802 - 2·60·80·cos 60° = 5200 => d = 20√13 km.","label":"Câu hỏi 30"},{"num":31,"topicId":"cos","prompt":"Cho tam giác ABC có các cạnh BC = a, CA = b, AB = c. Khẳng định nào sau đây ĐÚNG?","options":["a2 = b2 + c2 - 2bc·cos A","a2 = b2 + c2 + 2bc·cos A","a2 = b2 + c2 - bc·cos A","a2 = b2 + c2 - 2bc·sin A"],"answerText":"a2 = b2 + c2 - 2bc·cos A","explanation":"Công thức chuẩn định lí cosin trong tam giác.","label":"Câu hỏi 31"},{"num":32,"topicId":"cos","prompt":"Từ định lí cosin, biểu thức tính cos B nào sau đây đúng?","options":["cos B = (a2 + c2 - b2) / (2ac)","cos B = (a2 + b2 - c2) / (2ab)","cos B = (b2 + c2 - a2) / (2bc)","cos B = (a2 + c2 - b2) / (ac)"],"answerText":"cos B = (a2 + c2 - b2) / (2ac)","explanation":"Hệ quả định lí cosin tính góc B theo độ dài ba cạnh.","label":"Câu hỏi 32"},{"num":33,"topicId":"cos","prompt":"Cho tam giác ABC có cos A < 0. Khẳng định nào sau đây đúng về tam giác ABC?","options":["Góc A là góc nhọn","Góc A là góc tù","Góc A là góc vuông","Tam giác ABC đều"],"answerText":"Góc A là góc tù","explanation":"Cosin của góc tù luôn có giá trị âm (trên đường tròn lượng giác).","label":"Câu hỏi 33"},{"num":34,"topicId":"cos","prompt":"Cho tam giác ABC có b = 3, c = 4 và góc A = 60°. Độ dài cạnh a là:","options":["√13","13","√37","5"],"answerText":"√13","explanation":"a2 = 32 + 42 - 2·3·4·cos 60° = 9 + 16 - 12 = 13 => a = √13.","label":"Câu hỏi 34"},{"num":35,"topicId":"cos","prompt":"Khi góc A = 90°, hệ thức định lí cosin a2 = b2 + c2 - 2bc·cos A trở thành công thức nào?","options":["a2 = b2 + c2 - 2bc","a2 = b2 + c2","a2 = b2 + c2 + 2bc","a2 = b2 - c2"],"answerText":"a2 = b2 + c2","explanation":"Vì cos 90° = 0 nên định lí cosin suy biến thành định lí Pythagoras.","label":"Câu hỏi 35"},{"num":36,"topicId":"cos","prompt":"Cho tam giác ABC có ba cạnh a = 7, b = 5, c = 3. Giá trị của cos A bằng:","options":["-1/2","1/2","√3/2","-√3/2"],"answerText":"-1/2","explanation":"cos A = (52 + 32 - 72) / (2 · 5 · 3) = -15/30 = -1/2.","label":"Câu hỏi 36"},{"num":37,"topicId":"cos","prompt":"Cho tam giác ABC có a = 6, b = 7, c = 10. Khẳng định nào sau đây đúng?","options":["Tam giác ABC có góc C tù","Tam giác ABC có góc A tù","Tam giác ABC có góc B tù","Tam giác nhọn"],"answerText":"Tam giác ABC có góc C tù","explanation":"Cạnh c = 10 lớn nhất. cos C = (62 + 72 - 102)/(2·6·7) = -15/84 < 0 => góc C tù.","label":"Câu hỏi 37"},{"num":38,"topicId":"cos","prompt":"Công thức tính độ dài đường trung tuyến ma xuất phát từ đỉnh A là:","options":["ma2 = (2(b2 + c2) - a2) / 4","ma2 = (b2 + c2 - a2) / 2","ma2 = (2(b2 + c2) + a2) / 4","ma2 = (a2 + b2 - c2) / 4"],"answerText":"ma2 = (2(b2 + c2) - a2) / 4","explanation":"Công thức đường trung tuyến chuẩn trong tam giác.","label":"Câu hỏi 38"},{"num":39,"topicId":"cos","prompt":"Cho tam giác ABC có a = 6, b = 4, c = 4. Độ dài đường trung tuyến ma là:","options":["2","√7","√10","4"],"answerText":"√7","explanation":"ma2 = (2(42 + 42) - 62) / 4 = (64 - 36)/4 = 7 => ma = √7.","label":"Câu hỏi 39"},{"num":40,"topicId":"cos","prompt":"Cho tam giác ABC có b = 5, c = 8 và góc A = 120°. Độ dài cạnh a là:","options":["7","√129","119","109"],"answerText":"√129","explanation":"a2 = 52 + 82 - 2·5·8·cos 120° = 25 + 64 + 40 = 129 => a = √129.","label":"Câu hỏi 40"},{"num":41,"topicId":"cos","prompt":"Cho tam giác ABC thỏa mãn a2 = b2 + c2 - bc. Số đo góc A là:","options":["30°","45°","60°","120°"],"answerText":"60°","explanation":"2·cos A = 1 => cos A = 1/2 => góc A = 60°.","label":"Câu hỏi 41"},{"num":42,"topicId":"cos","prompt":"Cho tam giác ABC có a2 = b2 + c2 + bc. Số đo góc A là:","options":["135°","120°","60°","150°"],"answerText":"120°","explanation":"-2·cos A = 1 => cos A = -1/2 => góc A = 120°.","label":"Câu hỏi 42"},{"num":43,"topicId":"cos","prompt":"Cho tam giác ABC có b = 6, c = 8, góc A = 60°. Chu vi P của tam giác ABC là:","options":["14 + 2√13","14 + √13","20","14 + 2√37"],"answerText":"14 + 2√13","explanation":"a2 = 36 + 64 - 2·6·8·(1/2) = 52 => a = 2√13. Chu vi P = 6 + 8 + 2√13 = 14 + 2√13.","label":"Câu hỏi 43"},{"num":44,"topicId":"cos","prompt":"Cho tam giác ABC có a2 + b2 = c2. Giá trị của cos C bằng:","options":["1","0","1/2","-1"],"answerText":"0","explanation":"cos C = (a2 + b2 - c2)/(2ab) = 0/2ab = 0.","label":"Câu hỏi 44"},{"num":45,"topicId":"cos","prompt":"Cho tam giác ABC có b = 4, c = 5 và cos A = 3/5. Độ dài cạnh a là:","options":["√17","√21","5","4"],"answerText":"√17","explanation":"a2 = 16 + 25 - 2·4·5·(3/5) = 41 - 24 = 17 => a = √17.","label":"Câu hỏi 45"},{"num":46,"topicId":"cos","prompt":"Cho tam giác ABC có b = 6, c = 10, góc A = 60°. Độ dài đường trung tuyến ma bằng:","options":["√19","7","2√19","√37"],"answerText":"7","explanation":"a2 = 36 + 100 - 60 = 76. ma2 = (2(36+100) - 76)/4 = 49 => ma = 7.","label":"Câu hỏi 46"},{"num":47,"topicId":"cos","prompt":"Để tam giác ABC có góc C là góc nhọn thì các cạnh phải thỏa mãn điều kiện nào?","options":["a2 + b2 > c2","a2 + b2 < c2","a2 + b2 = c2","a + b > c"],"answerText":"a2 + b2 > c2","explanation":"Góc C nhọn <=> cos C > 0 <=> a2 + b2 - c2 > 0 <=> a2 + b2 > c2.","label":"Câu hỏi 47"},{"num":48,"topicId":"cos","prompt":"Cho tam giác ABC có b = 3, c = 4 và góc A = 60°. Bán kính R của đường tròn ngoại tiếp bằng:","options":["√(13/3)","√13","√39/3","√13/3"],"answerText":"√(13/3)","explanation":"a = √13. R = a/(2·sin A) = √13 / (2 · √3/2) = √(13/3).","label":"Câu hỏi 48"},{"num":49,"topicId":"cos","prompt":"Hình bình hành ABCD có AB = 4, AD = 6 và góc BAD = 60°. Độ dài đường chéo BD là:","options":["2√7","2√19","2√13","√52"],"answerText":"2√7","explanation":"Xét tam giác ABD: BD2 = 16 + 36 - 2·4·6·cos 60° = 28 => BD = 2√7.","label":"Câu hỏi 49"},{"num":50,"topicId":"cos","prompt":"Hình bình hành ABCD có AB = 4, AD = 6 và góc BAD = 60°. Độ dài đường chéo AC là:","options":["2√19","2√7","10","2√13"],"answerText":"2√19","explanation":"Góc ABC = 120°. AC2 = 16 + 36 - 2·4·6·cos 120° = 76 => AC = 2√19.","label":"Câu hỏi 50"},{"num":51,"topicId":"cos","prompt":"Cho tam giác ABC thỏa mãn a(a2 - c2) = b(b2 - c2) với a khác b. Tính góc C.","options":["60°","120°","45°","90°"],"answerText":"120°","explanation":"(a-b)(a2+ab+b2-c2) = 0 => a2+b2-c2 = -ab => cos C = -1/2 => góc C = 120°.","label":"Câu hỏi 51"},{"num":52,"topicId":"cos","prompt":"Cho tam giác ABC thỏa mãn b + c = 2a. Tính M = 2·sin B·sin C - cos A.","options":["1","1/2","3/2","0"],"answerText":"1/2","explanation":"Biến đổi hệ thức lượng kết hợp góc suy ra M = 1/2.","label":"Câu hỏi 52"},{"num":53,"topicId":"cos","prompt":"Cho tam giác ABC có a = 3, b = 5, c = 7. Tỉ số giữa đường trung tuyến ngắn nhất và dài nhất là:","options":["√19 / √139","√61 / √19","19 / 61","3 / 7"],"answerText":"√19 / √139","explanation":"mc nhỏ nhất = √19/2, ma lớn nhất = √139/2. Tỉ số = √19 / √139.","label":"Câu hỏi 53"},{"num":54,"topicId":"cos","prompt":"Cho tam giác ABC có mb2 + mc2 = 5ma2. Khẳng định nào sau đây đúng?","options":["Tam giác ABC vuông tại A","Tam giác cân tại A","Tam giác vuông tại B","Tam giác đều"],"answerText":"Tam giác ABC vuông tại A","explanation":"Thay công thức trung tuyến thu được b2 + c2 = a2 => vuông tại A.","label":"Câu hỏi 54"},{"num":55,"topicId":"cos","prompt":"Cho tam giác ABC. Khẳng định nào đúng về biểu thức P = cos A + cos B + cos C?","options":["1 < P <= 3/2","P >= 2","P <= 1","P = 3"],"answerText":"1 < P <= 3/2","explanation":"Bất đẳng thức lượng giác cơ bản trong mọi tam giác: 1 < cos A + cos B + cos C <= 3/2.","label":"Câu hỏi 55"},{"num":56,"topicId":"cos","prompt":"Hai tàu rời cảng O: tàu 1 chạy hướng Đông 30 km/h, tàu 2 chạy hướng N60°E 40 km/h. Sau 1.5h khoảng cách 2 tàu là:","options":["15√13 km","30√13 km","50 km","60 km"],"answerText":"15√13 km","explanation":"OA = 45km, OB = 60km, góc 60°. AB2 = 452 + 602 - 2·45·60·cos 60° = 2925 => AB = 15√13 km.","label":"Câu hỏi 56"},{"num":57,"topicId":"cos","prompt":"Đo khoảng cách A, B qua đầm lầy: CA = 120m, CB = 150m, góc ACB = 120°. Khoảng cách AB xấp xỉ:","options":["234 m","190 m","270 m","210 m"],"answerText":"234 m","explanation":"AB2 = 1202 + 1502 - 2·120·150·cos 120° = 54900 => AB ≈ 234.3 m.","label":"Câu hỏi 57"},{"num":58,"topicId":"cos","prompt":"Đường gom AC = 15km, BC = 20km, góc ACB = 135°. Chiều dài hầm thẳng AB tiết kiệm được so với đường gom là:","options":["2.6 km","32.4 km","35.0 km","5.2 km"],"answerText":"2.6 km","explanation":"AB2 = 225 + 400 - 2·15·20·cos 135° ≈ 1049.26 => AB ≈ 32.4 km. Tiết kiệm: 35 - 32.4 = 2.6 km.","label":"Câu hỏi 58"},{"num":59,"topicId":"cos","prompt":"Ba điểm A, B, C chân tháp có AC = 80m, BC = 140m, AB = 100m. Góc BAC gần bằng:","options":["101.5°","60°","78.5°","120°"],"answerText":"101.5°","explanation":"cos A = (802 + 1002 - 1402)/(2·80·100) = -0.2 => góc A ≈ 101.54°.","label":"Câu hỏi 59"},{"num":60,"topicId":"cos","prompt":"Thang chữ A có hai nhánh dài 2.5m, mở rộng chân 1.5m. Góc mở ở đỉnh thang gần bằng:","options":["35°","17.5°","40°","70°"],"answerText":"35°","explanation":"cos α = (2.52 + 2.52 - 1.52)/(2·2.5·2.5) = 0.82 => α ≈ 34.9° ≈ 35°.","label":"Câu hỏi 60"},{"num":61,"topicId":"area","prompt":"Công thức tính diện tích S của tam giác ABC theo hai cạnh a, b và góc C kẹp giữa là:","options":["S = 1/2·ab·sin C","S = 1/2·ab·cos C","S = ab·sin C","S = 1/2·ab·sin A"],"answerText":"S = 1/2·ab·sin C","explanation":"Công thức diện tích tam giác theo 2 cạnh và góc kẹp giữa.","label":"Câu hỏi 61"},{"num":62,"topicId":"area","prompt":"Gọi p là nửa chu vi tam giác ABC. Công thức Heron tính diện tích S là:","options":["S = √((p-a)(p-b)(p-c))","S = √(p(p-a)(p-b)(p-c))","S = p(p-a)(p-b)(p-c)","S = √(p(a-p)(b-p)(c-p))"],"answerText":"S = √(p(p-a)(p-b)(p-c))","explanation":"Công thức Heron chuẩn cho diện tích tam giác.","label":"Câu hỏi 62"},{"num":63,"topicId":"area","prompt":"Cho tam giác ABC có 3 cạnh a, b, c và R là bán kính đường tròn ngoại tiếp. Diện tích S là:","options":["S = abc / R","S = abc / (2R)","S = abc / (4R)","S = 4Rabc"],"answerText":"S = abc / (4R)","explanation":"Công thức diện tích liên hệ bán kính đường tròn ngoại tiếp R.","label":"Câu hỏi 63"},{"num":64,"topicId":"area","prompt":"Cho tam giác ABC có nửa chu vi p và r là bán kính đường tròn nội tiếp. Diện tích S tính bởi:","options":["S = p·r","S = 1/2·p·r","S = 2p·r","S = p / r"],"answerText":"S = p·r","explanation":"Công thức diện tích liên hệ bán kính đường tròn nội tiếp r.","label":"Câu hỏi 64"},{"num":65,"topicId":"area","prompt":"Cho tam giác ABC có b = 4, c = 6 và góc A = 30°. Diện tích tam giác ABC bằng:","options":["12","6","6√3","12√3"],"answerText":"6","explanation":"S = 1/2 · 4 · 6 · sin 30° = 6.","label":"Câu hỏi 65"},{"num":66,"topicId":"area","prompt":"Cho tam giác ABC có độ dài ba cạnh a = 3, b = 4, c = 5. Diện tích tam giác bằng:","options":["6","12","60","10"],"answerText":"6","explanation":"p = 6. S = √(6·3·2·1) = 6 (hoặc tam giác vuông S = 1/2·3·4 = 6).","label":"Câu hỏi 66"},{"num":67,"topicId":"area","prompt":"Cho tam giác ABC có diện tích S = 24 và nửa chu vi p = 8. Bán kính r nội tiếp bằng:","options":["r = 3","r = 4","r = 2","r = 6"],"answerText":"r = 3","explanation":"r = S / p = 24 / 8 = 3.","label":"Câu hỏi 67"},{"num":68,"topicId":"area","prompt":"Cho tam giác ABC có a = 6, b = 8, c = 10 và diện tích S = 24. Bán kính R ngoại tiếp bằng:","options":["5","10","2.5","4"],"answerText":"5","explanation":"R = abc / (4S) = (6·8·10) / 96 = 5.","label":"Câu hỏi 68"},{"num":69,"topicId":"area","prompt":"Cho tam giác ABC đều cạnh a. Diện tích tam giác ABC bằng:","options":["a2√3 / 4","a2√3 / 2","a2 / 2","a2√3"],"answerText":"a2√3 / 4","explanation":"S = 1/2 · a · a · sin 60° = a2√3 / 4.","label":"Câu hỏi 69"},{"num":70,"topicId":"area","prompt":"Cho tam giác ABC có S = 30 và cạnh a = 10. Độ dài đường cao ha kẻ từ A là:","options":["3","6","12","5"],"answerText":"6","explanation":"ha = 2S / a = 60 / 10 = 6.","label":"Câu hỏi 70"},{"num":71,"topicId":"area","prompt":"Cho tam giác ABC có b = 3, c = 5 và góc A = 120°. Diện tích tam giác ABC là:","options":["15√3/4","15/4","15√3/2","15√3"],"answerText":"15√3/4","explanation":"S = 1/2 · 3 · 5 · sin 120° = 15√3 / 4.","label":"Câu hỏi 71"},{"num":72,"topicId":"area","prompt":"Cho tam giác ABC có các cạnh a = 5, b = 7, c = 8. Bán kính r của đường tròn nội tiếp bằng:","options":["√3","2√3","√3/2","3"],"answerText":"√3","explanation":"p = 10. S = √(10·5·3·2) = 10√3. r = S/p = √3.","label":"Câu hỏi 72"},{"num":73,"topicId":"area","prompt":"Cho tam giác ABC có b = 8, c = 5, góc A = 150°. Đường cao hb kẻ từ B có độ dài bằng:","options":["2.5","4","2.5√3","5"],"answerText":"2.5","explanation":"S = 1/2·8·5·sin 150° = 10. hb = 2S/b = 20/8 = 2.5.","label":"Câu hỏi 73"},{"num":74,"topicId":"area","prompt":"Biểu thức biểu diễn diện tích S qua R và 3 góc sin A, sin B, sin C là:","options":["S = 2R2·sin A·sin B·sin C","S = R2·sin A·sin B·sin C","S = 4R2·sin A·sin B·sin C","S = 1/2·R2·sin A·sin B·sin C"],"answerText":"S = 2R2·sin A·sin B·sin C","explanation":"S = abc/(4R) = (2R sin A · 2R sin B · 2R sin C)/(4R) = 2R2 sin A sin B sin C.","label":"Câu hỏi 74"},{"num":75,"topicId":"area","prompt":"Trên cạnh BC của tam giác ABC lấy D sao cho BD = 2DC. Tỉ số SABD / SABC bằng:","options":["2/3","1/3","1/2","3/4"],"answerText":"2/3","explanation":"Chung đường cao hạ từ A, tỉ số diện tích bằng tỉ số đáy BD/BC = 2/3.","label":"Câu hỏi 75"},{"num":76,"topicId":"area","prompt":"Cho tam giác ABC có góc A = 60°, b = 6, c = 10. Độ dài đường cao ha là:","options":["15√3 / √19","30√3 / 19","15 / √19","30 / √19"],"answerText":"15√3 / √19","explanation":"S = 15√3. a = 2√19. ha = 2S/a = 15√3 / √19.","label":"Câu hỏi 76"},{"num":77,"topicId":"area","prompt":"Tam giác ABC vuông tại A có b = 6, c = 8. Tỉ số R/r giữa bán kính ngoại tiếp và nội tiếp là:","options":["5/2","2/5","5/4","2"],"answerText":"5/2","explanation":"a = 10 => R = 5. p = 12, S = 24 => r = 2. Tỉ số R/r = 5/2.","label":"Câu hỏi 77"},{"num":78,"topicId":"area","prompt":"Tứ giác ABCD có 2 đường chéo AC = 8cm, BD = 10cm vuông góc tại O. Diện tích ABCD bằng:","options":["40 cm2","80 cm2","20 cm2","60 cm2"],"answerText":"40 cm2","explanation":"Tứ giác có 2 đường chéo vuông góc: S = 1/2 · d1 · d2 = 40 cm2.","label":"Câu hỏi 78"},{"num":79,"topicId":"area","prompt":"Hình bình hành ABCD có AB = 5, AD = 8 và góc BAD = 45°. Diện tích ABCD bằng:","options":["20√2","10√2","40√2","20"],"answerText":"20√2","explanation":"S = AB · AD · sin 45° = 5 · 8 · √2/2 = 20√2.","label":"Câu hỏi 79"},{"num":80,"topicId":"area","prompt":"Nếu hai cạnh b, c tăng lên 2 lần và giữ nguyên góc A thì diện tích tam giác thay đổi thế nào?","options":["Tăng 4 lần","Tăng 2 lần","Tăng 8 lần","Không đổi"],"answerText":"Tăng 4 lần","explanation":"S' = 1/2 · (2b) · (2c) · sin A = 4S.","label":"Câu hỏi 80"},{"num":81,"topicId":"area","prompt":"Tam giác ABC có hai cạnh b = 6, c = 8. Diện tích lớn nhất có thể đạt được là:","options":["24","48","12","24√3"],"answerText":"24","explanation":"S = 24·sin A <= 24 (đạt lớn nhất khi góc A = 90°).","label":"Câu hỏi 81"},{"num":82,"topicId":"area","prompt":"Trên AB lấy M sao cho AM = 1/3 AB, trên AC lấy N sao cho AN = 3/4 AC. Tỉ số SAMN / SABC là:","options":["1/4","1/3","1/2","5/12"],"answerText":"1/4","explanation":"Tỉ số diện tích = (AM/AB) · (AN/AC) = (1/3) · (3/4) = 1/4.","label":"Câu hỏi 82"},{"num":83,"topicId":"area","prompt":"Cho tam giác ABC thỏa mãn S = 1/4·(a2 + b2). Tam giác ABC là tam giác gì?","options":["Vuông cân tại C","Tam giác đều","Vuông tại A","Cân tại A"],"answerText":"Vuông cân tại C","explanation":"S = 1/2 ab sin C <= 1/2 ab <= 1/4(a2+b2). Dấu '=' xảy ra khi a = b và góc C = 90°.","label":"Câu hỏi 83"},{"num":84,"topicId":"area","prompt":"Trong các tam giác có cùng chu vi 2p, tam giác nào có diện tích S lớn nhất?","options":["Tam giác đều","Tam giác vuông cân","Tam giác tù","Tam giác cân 30°"],"answerText":"Tam giác đều","explanation":"Theo bất đẳng thức Isoperimetric, tam giác đều tối ưu diện tích nhất với chu vi cố định.","label":"Câu hỏi 84"},{"num":85,"topicId":"area","prompt":"Cho tam giác ABC có 3 đường cao ha = 6, hb = 8, hc = 12. Diện tích S xấp xỉ bằng:","options":["16.5","32.0","24.0","12.8"],"answerText":"16.5","explanation":"a = 2S/6, b = 2S/8, c = 2S/12. Dùng Heron giải phương trình thu được S ≈ 16.52.","label":"Câu hỏi 85"},{"num":86,"topicId":"area","prompt":"Mảnh đất tam giác có AB = 20m, AC = 25m, góc A = 60°. Giá 15 triệu/m2. Giá trị đất xấp xỉ:","options":["3.25 tỷ","2.16 tỷ","4.33 tỷ","1.87 tỷ"],"answerText":"3.25 tỷ","explanation":"S = 1/2·20·25·sin 60° ≈ 216.5 m2. Tổng tiền ≈ 216.5 · 15 triệu ≈ 3.25 tỷ.","label":"Câu hỏi 86"},{"num":87,"topicId":"area","prompt":"Hồ nước tam giác có AB = 80m, AC = 100m, trung tuyến AM = 60m. Diện tích mặt hồ bằng:","options":["2400 m2","4800 m2","1200√3 m2","3600 m2"],"answerText":"2400 m2","explanation":"Dùng công thức trung tuyến tính ra BC = 40√10m, sau đó tính diện tích S = 2400 m2.","label":"Câu hỏi 87"},{"num":88,"topicId":"area","prompt":"Đồng cỏ AB = 120m, BC = 150m, CA = 200m. Bán kính R tối thiểu vòi phun tưới hết cỏ là:","options":["108.9 m","200 m","85.4 m","150 m"],"answerText":"108.9 m","explanation":"p = 235m => S ≈ 8966.3 m2. R = abc / (4S) ≈ 108.9 m.","label":"Câu hỏi 88"},{"num":89,"topicId":"area","prompt":"Bồn hoa tam giác 13m, 14m, 15m. Bán kính r của vòi nước nội tiếp là:","options":["4 m","3 m","5 m","4.5 m"],"answerText":"4 m","explanation":"p = 21m, S = 84 m2 => r = S/p = 84/21 = 4 m.","label":"Câu hỏi 89"},{"num":90,"topicId":"area","prompt":"Thửa đất AB = 60m, AC = 90m, góc A = 60°. Ranh giới trung tuyến AD chia đôi diện tích dài xấp xỉ:","options":["65 m","45 m","52 m","39 m"],"answerText":"65 m","explanation":"a2 = 6300. ma2 = (2(3600+8100) - 6300)/4 = 4275 => AD ≈ 65.38 m ≈ 65 m.","label":"Câu hỏi 90"},{"num":91,"topicId":"solve","prompt":"Cho tam giác ABC có góc B = 60°, góc C = 45° và cạnh b = 6. Số đo góc A là:","options":["75°","80°","65°","105°"],"answerText":"75°","explanation":"Góc A = 180° - (60° + 45°) = 75°.","label":"Câu hỏi 91"},{"num":92,"topicId":"solve","prompt":"Cho tam giác ABC có a = 4, b = 5 và góc C = 60°. Độ dài cạnh c là:","options":["√21","21","√41","6"],"answerText":"√21","explanation":"c2 = 16 + 25 - 20 = 21 => c = √21.","label":"Câu hỏi 92"},{"num":93,"topicId":"solve","prompt":"Cho tam giác ABC có a = 7, b = 8, c = 9. Góc lớn nhất của tam giác ABC là góc nào?","options":["Góc C","Góc B","Góc A","Ba góc bằng nhau"],"answerText":"Góc C","explanation":"Cạnh c = 9 lớn nhất nên góc C đối diện là góc lớn nhất.","label":"Câu hỏi 93"},{"num":94,"topicId":"solve","prompt":"Bài toán giải tam giác khi biết 2 cạnh a, b và góc C kẹp giữa luôn cho ra:","options":["Đúng 1 tam giác duy nhất","2 tam giác","Vô số tam giác","Không có tam giác nào"],"answerText":"Đúng 1 tam giác duy nhất","explanation":"Trường hợp C-G-C xác định duy nhất 1 tam giác.","label":"Câu hỏi 94"},{"num":95,"topicId":"solve","prompt":"Cho tam giác ABC có góc A = 45°, góc B = 60° và b = 4√6. Cạnh a bằng:","options":["8","4√3","4√2","6"],"answerText":"8","explanation":"a = b·sin A / sin B = 4√6 · (√2/2) / (√3/2) = 8.","label":"Câu hỏi 95"},{"num":96,"topicId":"solve","prompt":"Cho tam giác ABC có a = 10, góc A = 30°. Bán kính đường tròn ngoại tiếp R là:","options":["10","5","20","10√3"],"answerText":"10","explanation":"R = a / (2·sin A) = 10 / (2 · 0.5) = 10.","label":"Câu hỏi 96"},{"num":97,"topicId":"solve","prompt":"Cho tam giác ABC có a = 6, b = 8, góc C = 30°. Độ dài đường cao ha kẻ từ A là:","options":["4","3","2.4","5"],"answerText":"4","explanation":"S = 1/2·6·8·sin 30° = 12. ha = 2S/a = 24/6 = 4.","label":"Câu hỏi 97"},{"num":98,"topicId":"solve","prompt":"Cho tam giác ABC có góc A = 30°, góc B = 60°. Tỉ số ba cạnh a : b : c là:","options":["1 : √3 : 2","1 : 2 : 3","1 : 1 : √2","1 : √3 : 2"],"answerText":"1 : √3 : 2","explanation":"Góc C = 90°. a : b : c = sin 30° : sin 60° : sin 90° = 1/2 : √3/2 : 1 = 1 : √3 : 2.","label":"Câu hỏi 98"},{"num":99,"topicId":"solve","prompt":"Cho tam giác ABC có a = 3, b = 3√3, góc A = 30°. Số đo góc B nhọn là:","options":["60°","45°","30°","90°"],"answerText":"60°","explanation":"sin B = b·sin A / a = 3√3 · (1/2) / 3 = √3/2 => B = 60°.","label":"Câu hỏi 99"},{"num":100,"topicId":"solve","prompt":"Cây cối vuông góc mặt đất có bóng dài 8m khi góc nâng mặt trời 60°. Chiều cao cây là:","options":["8√3 m","8√3/3 m","8 m","16 m"],"answerText":"8√3 m","explanation":"h = 8 · tan 60° = 8√3 m.","label":"Câu hỏi 100"},{"num":101,"topicId":"solve","prompt":"Cho tam giác ABC có a = 4, b = 5, góc A = 30°. Giá trị sin B và số lượng góc B thỏa mãn là:","options":["sin B = 5/8, có 2 giá trị góc B","sin B = 5/8, chỉ 1 giá trị","sin B = 4/5","Không tồn tại"],"answerText":"sin B = 5/8, có 2 giá trị góc B","explanation":"sin B = 5/8 < 1. Vì b > a nên cả 2 góc B (nhọn và tù) đều hợp lệ.","label":"Câu hỏi 101"},{"num":102,"topicId":"solve","prompt":"Tứ giác ABCD có AB = 3, BC = 4, góc B = 90°, CD = 12, góc ACD = 90°. Độ dài AD là:","options":["13","15","5","√153"],"answerText":"13","explanation":"AC = √(32+42) = 5. AD = √(52+122) = 13.","label":"Câu hỏi 102"},{"num":103,"topicId":"solve","prompt":"Cho tam giác ABC có b = 6, c = 12, góc A = 60°. Độ dài phân giác trong AD là:","options":["4√3","4","6√3","3√3"],"answerText":"4√3","explanation":"AD = 2bc·cos(A/2) / (b+c) = 2·6·12·(√3/2) / 18 = 4√3.","label":"Câu hỏi 103"},{"num":104,"topicId":"solve","prompt":"Cho tam giác ABC có a = 10, góc B = 45°, góc C = 60°. Diện tích S xấp xỉ:","options":["31.7","25.0","43.3","50.0"],"answerText":"31.7","explanation":"Góc A = 75°. S = a2 sin B sin C / (2 sin A) = 100 · (√2/2) · (√3/2) / (2 sin 75°) ≈ 31.7.","label":"Câu hỏi 104"},{"num":105,"topicId":"solve","prompt":"Tam giác ABC vuông tại A, AH = 12cm, HB = 9cm. Chu vi tam giác ABC bằng:","options":["60 cm","48 cm","50 cm","54 cm"],"answerText":"60 cm","explanation":"HC = 144/9 = 16cm => BC = 25cm. AB = 15cm, AC = 20cm. Chu vi = 15+20+25 = 60 cm.","label":"Câu hỏi 105"},{"num":106,"topicId":"solve","prompt":"Khoảng cách từ M đến Ox, Oy trong góc vuông xOy lần lượt là 3 và 4. Khoảng cách OM là:","options":["5","7","√7","12"],"answerText":"5","explanation":"OM = √(32 + 42) = 5.","label":"Câu hỏi 106"},{"num":107,"topicId":"solve","prompt":"Hai người xuất phát từ A: người 1 đi Bắc 12 km/h, người 2 đi Đông 9 km/h. Sau 2h khoảng cách là:","options":["30 km","42 km","21 km","15 km"],"answerText":"30 km","explanation":"d = √((12·2)2 + (9·2)2) = √(242 + 182) = 30 km.","label":"Câu hỏi 107"},{"num":108,"topicId":"solve","prompt":"Tháp CD thẳng hàng A, B. AB = 40m, góc nâng tại A là 30°, tại B là 45°. Chiều cao tháp h gần nhất:","options":["54.6 m","40.0 m","69.3 m","34.6 m"],"answerText":"54.6 m","explanation":"h(cot 30° - cot 45°) = 40 => h(√3 - 1) = 40 => h ≈ 54.64 m.","label":"Câu hỏi 108"},{"num":109,"topicId":"solve","prompt":"Đo rộng sông: AB = 50m dọc bờ, góc CAB = 50°, góc CBA = 70°. Bề rộng sông xấp xỉ:","options":["41.6 m","47.0 m","38.2 m","53.2 m"],"answerText":"41.6 m","explanation":"Góc C = 60°. AC = 50·sin 70° / sin 60° ≈ 54.25m. Chiều rộng h = AC·sin 50° ≈ 41.6 m.","label":"Câu hỏi 109"},{"num":110,"topicId":"solve","prompt":"Hải đăng 80m nhìn 2 thuyền thẳng hàng dưới góc hạ 45° và 30°. Khoảng cách 2 thuyền là:","options":["80(√3 - 1) m","80√3 m","80 m","160 m"],"answerText":"80(√3 - 1) m","explanation":"d = 80·cot 30° - 80·cot 45° = 80(√3 - 1) m.","label":"Câu hỏi 110"},{"num":111,"topicId":"solve","prompt":"Tam giác ABC có AB = 4, AC = 6, góc A = 120°. Trên BC lấy D sao cho góc BAD = 60°. Độ dài AD là:","options":["2.4","3.0","2.0","3.2"],"answerText":"2.4","explanation":"SABC = SABD + SADC => 1/2·4·6·sin 120° = 1/2·4·AD·sin 60° + 1/2·6·AD·sin 60° => AD = 2.4.","label":"Câu hỏi 111"},{"num":112,"topicId":"solve","prompt":"M di động trên BC của tam giác nhọn ABC. E, F là hình chiếu của M lên AB, AC. EF nhỏ nhất khi:","options":["M là chân đường cao kẻ từ A","M là trung điểm BC","M trùng B","M là chân phân giác"],"answerText":"M là chân đường cao kẻ từ A","explanation":"EF = AM·sin A. EF nhỏ nhất khi AM nhỏ nhất <=> M là chân đường cao kẻ từ A.","label":"Câu hỏi 112"},{"num":113,"topicId":"solve","prompt":"Tam giác ABC có góc A = 60° cố định và b + c = 12. Cạnh a đạt giá trị nhỏ nhất bằng:","options":["6","6√3","4√3","3√6"],"answerText":"6","explanation":"a2 = (b+c)2 - 3bc = 144 - 3bc >= 144 - 3·36 = 36 => a >= 6 (dấu '=' khi b = c = 6).","label":"Câu hỏi 113"},{"num":114,"topicId":"solve","prompt":"Tháp CD cao h đứng trên đồi nghiêng β. Chân đồi A nhìn đỉnh D góc α (α > β). Độ dài AD là:","options":["AD = h·cos β / sin(α - β)","AD = h·sin β / sin(α - β)","AD = h·cos α / sin(α - β)","AD = h·sin α / cos(α - β)"],"answerText":"AD = h·cos β / sin(α - β)","explanation":"Công thức định lí sin trong tam giác ACD cho kết quả chuẩn AD = h·cos β / sin(α - β).","label":"Câu hỏi 114"},{"num":115,"topicId":"solve","prompt":"Ba mốc A, B, C thẳng hàng AB = 4km, BC = 6km. Tàu P nhìn APB = 30°, BPC = 30°. Khoảng cách PB gần nhất:","options":["8.7 km","6.5 km","10.2 km","7.2 km"],"answerText":"8.7 km","explanation":"PB là phân giác góc APC. Áp dụng định lí sin/cos tính được PB ≈ 8.7 km.","label":"Câu hỏi 115"},{"num":116,"topicId":"solve","prompt":"Đo nhà cao tầng: AB = 30m, góc nâng tại A là 35°, tại B là 55°. Máy kinh vĩ cao 1.4m. Tòa nhà cao:","options":["42.6 m","37.0 m","38.4 m","53.6 m"],"answerText":"42.6 m","explanation":"h' = 30 / (cot 35° - cot 55°) ≈ 41.2m. Tổng chiều cao h = 41.2 + 1.4 = 42.6 m.","label":"Câu hỏi 116"},{"num":117,"topicId":"solve","prompt":"Trạm A, B cách nhau 10km. Trạm A thấy lửa hướng N40°E, trạm B thấy lửa N30°W. Khoảng cách A đến lửa là:","options":["9.2 km","7.5 km","8.2 km","10.5 km"],"answerText":"9.2 km","explanation":"Góc A = 50°, B = 60° => C = 70°. AC = 10 · sin 60° / sin 70° ≈ 9.2 km.","label":"Câu hỏi 117"},{"num":118,"topicId":"solve","prompt":"Mái nhà Thái cân rộng BC = 8m, cao AH = 3m. Độ dốc góc B và chiều dài xà gồ AB là:","options":["36.9° và 5 m","45° và 4√2 m","30° và 6 m","53.1° và 5 m"],"answerText":"36.9° và 5 m","explanation":"BH = 4m => AB = √(32+42) = 5m. tan B = 3/4 => góc B ≈ 36.9°.","label":"Câu hỏi 118"},{"num":119,"topicId":"solve","prompt":"Máy bay hạ cánh từ độ cao 1000m, góc nghiêng 3°. Khoảng cách theo đường bay nghiêng đến điểm tiếp đất là:","options":["19107 m","19081 m","15000 m","20000 m"],"answerText":"19107 m","explanation":"L = 1000 / sin 3° ≈ 19107 m.","label":"Câu hỏi 119"},{"num":120,"topicId":"solve","prompt":"Vệ tinh cao 36000km, bán kính Trái Đất 6400km. Góc mở phủ tối đa bề mặt Trái Đất xấp xỉ:","options":["35°","17°","25°","45°"],"answerText":"35°","explanation":"sin(α/2) = 6400 / (36000 + 6400) = 6400 / 42400 ≈ 0.1509 => α/2 ≈ 8.68° => α ≈ 35°.","label":"Câu hỏi 120"}];
function createQuestionSet(topicId){
  // Cân bằng vị trí đáp án đúng: mỗi chủ đề 30 câu có 7 hoặc 8 đáp án ở mỗi vị trí A/B/C/D.
  const questions=QUESTION_BANK.filter(q=>q.topicId===topicId);
  const positions=questions.map((_,i)=>i%4);
  for(let i=positions.length-1;i>0;i--){
    const j=Math.floor(Math.random()*(i+1));
    [positions[i],positions[j]]=[positions[j],positions[i]];
  }
  return questions.map((q,index)=>{
    const {num,prompt,options,answerText,explanation,label}=q;
    const correctIndex=options.indexOf(answerText);
    const wrongOptions=options.filter((_,i)=>i!==correctIndex);
    for(let i=wrongOptions.length-1;i>0;i--){
      const j=Math.floor(Math.random()*(i+1));
      [wrongOptions[i],wrongOptions[j]]=[wrongOptions[j],wrongOptions[i]];
    }
    const shuffled=wrongOptions.slice();
    shuffled.splice(positions[index],0,answerText);
    return {id:`${topicId}_word_${num}`,topicId,kind:'word_question',p:{},serial:num,prompt,explanation,correctValue:null,unit:'',digits:0,label,options:shuffled,answerText,sourceNumber:num};
  });
}
function similarQuestion(q,index){
  // Tạo bài mới cùng mạch kiến thức, thay dữ kiện và tính lại đáp án/lời giải.
  const rand=(min,max)=>Math.floor(Math.random()*(max-min+1))+min;
  const pick=items=>items[rand(0,items.length-1)];
  const topic=q.topicId;
  let kind,p;
  if(topic==='sin'){
    // Các bài luyện định lí sin: tìm cạnh hoặc tìm góc từ dữ kiện mới.
    kind=pick(['sin_find_side','sin_find_angle','sin_find_side2']);
    if(kind==='sin_find_side') p={a:rand(8,18),A:pick([35,40,45,50,55,60]),B:pick([35,40,45,50,55,60,65])};
    else if(kind==='sin_find_angle') p={a:rand(14,22),A:pick([35,40,45,50,55,60]),b:rand(6,12)};
    else p={c:rand(9,18),C:pick([55,60,65,70,75,80]),A:pick([30,35,40,45,50])};
  }else if(topic==='cos'){
    kind=pick(['cos_side','cos_angle']);
    if(kind==='cos_side') p={a:rand(5,12),b:rand(6,13),C:pick([40,50,60,70,80,90,100,110])};
    else {const a=rand(6,10),b=rand(7,12),C=pick([45,60,75,90]);p={a,b,c:Math.sqrt(a*a+b*b-2*a*b*Math.cos(C*Math.PI/180))};}
  }else if(topic==='area'){
    kind=pick(['area_find','area_solve_side','area_find_angle']);
    p={a:rand(6,14),b:rand(7,15),C:pick([30,45,60,75,90])};
  }else{
    kind=pick(['solve_cos_side','sum_angles']);
    if(kind==='solve_cos_side') p={a:rand(5,12),b:rand(6,13),C:pick([40,50,60,70,80,90,100])};
    else {const A=pick([35,40,45,50,55,60]),B=pick([35,40,45,50,55,60]);p={A,B};}
  }
  return buildQuestion(topic,kind,p,5000+index);
}

function startQuiz(topicId,questions=null,mode='main'){const topic=topicById(topicId);currentQuiz={topicId,topic,mode,questions:questions||createQuestionSet(topicId),answers:{},startedAt:Date.now()};document.getElementById('dashboardView').classList.add('hidden');showScreen('quizView');document.getElementById('quizTitle').textContent=topic.name;document.getElementById('quizDescription').textContent=mode==='retry'?`Làm ${currentQuiz.questions.length} câu mới cùng dạng, đã thay số từ lỗi sai · Mã HS ${studentCode}`:'30 câu trắc nghiệm · Mã HS '+studentCode;document.getElementById('submitBtn').textContent=mode==='retry'?'Nộp bài luyện lại →':'Nộp bài & chấm điểm →';document.getElementById('backToDashboardBtn').textContent='← Vòng quay';renderQuestions();window.scrollTo({top:0,behavior:'smooth'})}
function renderQuestions(){const grid=document.getElementById('questionGrid');grid.innerHTML='';currentQuiz.questions.forEach((q,idx)=>{const card=document.createElement('article');card.className='question-card';card.id='card_'+q.id;const head=document.createElement('div');head.className='question-head';head.innerHTML=`<span class="q-number">CÂU ${idx+1}</span><span class="q-kind">${escapeHtml(q.label)}</span>`;const prompt=document.createElement('div');prompt.className='question-prompt';prompt.textContent=q.prompt;const options=document.createElement('div');options.className='options-list';q.options.forEach((opt,optIndex)=>{const btn=document.createElement('button');btn.type='button';btn.className='option-btn';btn.dataset.value=opt;btn.innerHTML=`<span class="option-letter">${String.fromCharCode(65+optIndex)}</span><span>${escapeHtml(opt)}</span>`;btn.addEventListener('click',()=>selectAnswer(q.id,opt,card));options.appendChild(btn)});const feedback=document.createElement('div');feedback.className='feedback hidden';feedback.id='feedback_'+q.id;card.append(head,prompt,options,feedback);grid.appendChild(card)});updateQuizProgress()}
function selectAnswer(qid,choice,card){if(Object.prototype.hasOwnProperty.call(currentQuiz.answers,qid))return;const q=currentQuiz.questions.find(x=>x.id===qid);currentQuiz.answers[qid]=choice;const correct=choice===q.answerText;card.classList.add(correct?'answered-correct':'answered-wrong');card.querySelectorAll('.option-btn').forEach(btn=>{btn.disabled=true;if(btn.dataset.value===q.answerText)btn.classList.add('correct-choice');if(btn.dataset.value===choice&&!correct)btn.classList.add('wrong-choice');if(btn.dataset.value===choice&&correct)btn.classList.add('selected')});const feedback=document.getElementById('feedback_'+qid);feedback.className='feedback '+(correct?'good':'bad');feedback.innerHTML=`<strong>${correct?'✓ Chính xác!':'✕ Chưa đúng. Đáp án đúng: '+escapeHtml(q.answerText)}</strong><p>${escapeHtml(q.explanation)}</p>`;updateQuizProgress()}
function updateQuizProgress(){if(!currentQuiz)return;const total=currentQuiz.questions.length,answered=Object.keys(currentQuiz.answers).length,pct=Math.round(answered/total*100);document.getElementById('progressText').textContent=`Đã trả lời ${answered}/${total} câu`;document.getElementById('progressPercent').textContent=pct+'%';document.getElementById('quizProgressFill').style.width=pct+'%';document.getElementById('footerCount').textContent=`${answered}/${total} câu đã chọn`}
document.getElementById('submitBtn').addEventListener('click',submitQuiz);
document.getElementById('backToDashboardBtn').addEventListener('click',()=>{if(currentQuiz&&Object.keys(currentQuiz.answers).length===0){showScreen('dashboardView');document.getElementById('dashboardView').classList.remove('hidden');window.scrollTo({top:0,behavior:'smooth'});return}if(currentQuiz&&Object.keys(currentQuiz.answers).length>0){const ok=confirm('Bạn đang làm dở bài. Nếu quay lại, câu trả lời của lượt này sẽ không được chấm. Bạn vẫn muốn quay lại?');if(!ok)return}currentQuiz=null;showScreen('dashboardView');document.getElementById('dashboardView').classList.remove('hidden');renderDashboard();window.scrollTo({top:0,behavior:'smooth'})});
function submitQuiz(){if(!currentQuiz)return;const qs=currentQuiz.questions;const correctQs=qs.filter(q=>currentQuiz.answers[q.id]===q.answerText);const wrongQs=qs.filter(q=>currentQuiz.answers[q.id]!==q.answerText);const answered=Object.keys(currentQuiz.answers).length;const score=correctQs.length/qs.length*10;const now=Date.now();const s=profile.topics[currentQuiz.topicId];s.sessions+=1;s.lastAt=now;qs.forEach(q=>{if(currentQuiz.answers[q.id]===q.answerText)s.correct+=1;else s.wrong+=1});s.answered=s.correct+s.wrong;const result={topicId:currentQuiz.topicId,topicName:currentQuiz.topic.name,mode:currentQuiz.mode,total:qs.length,correct:correctQs.length,wrong:wrongQs.length,answered,score,at:now,wrongQuestions:wrongQs};profile.history.unshift({topicId:result.topicId,topicName:result.topicName,mode:result.mode,total:result.total,correct:result.correct,score:result.score,at:result.at});profile.history=profile.history.slice(0,40);saveDatabase();lastResult=result;renderResult(result);showScreen('resultView');renderDashboard();window.scrollTo({top:0,behavior:'smooth'})}
function renderResult(result){const topic=topicById(result.topicId);document.getElementById('resultTitle').textContent=result.mode==='retry'?'Hoàn thành lượt luyện lại!':'Bạn đã hoàn thành lượt ôn tập!';document.getElementById('resultSub').textContent=topic.name+' · '+(result.mode==='retry'?'Bài mới cùng dạng, thay số từ những lỗi sai':'Bài 30 câu theo chủ đề');document.getElementById('resultScore').textContent=fmt(result.score,1);document.getElementById('resultCorrect').textContent=`${result.correct}/${result.total}`;document.getElementById('resultWrong').textContent=result.wrong;document.getElementById('resultPercent').textContent=fmt(result.correct/result.total*100,1)+'%';const wrongList=document.getElementById('wrongList');wrongList.innerHTML='';if(result.wrongQuestions.length===0){wrongList.innerHTML='<div class="empty-state">🎉 Tuyệt vời! Bạn đã trả lời đúng tất cả câu trong lượt này.</div>'}else{result.wrongQuestions.forEach((q,i)=>{const item=document.createElement('div');item.className='wrong-item';const chosen=currentQuiz.answers[q.id];item.innerHTML=`<strong>Câu ${i+1}. ${escapeHtml(q.prompt)}</strong><p>Bạn chọn: <b>${chosen?escapeHtml(chosen):'Chưa trả lời'}</b></p><p class="right-answer">Đáp án đúng: ${escapeHtml(q.answerText)}</p><p>${escapeHtml(q.explanation)}</p>`;wrongList.appendChild(item)})}const retryActions=document.getElementById('retryActions');retryActions.innerHTML='';if(result.wrongQuestions.length){const retry=document.createElement('button');retry.type='button';retry.className='primary-btn';retry.textContent=`Làm ${result.wrongQuestions.length} câu mới cùng dạng →`;retry.addEventListener('click',()=>{const similar=result.wrongQuestions.map((q,i)=>similarQuestion(q,i+1));startQuiz(result.topicId,similar,'retry')});retryActions.appendChild(retry)}else{const spin=document.createElement('button');spin.type='button';spin.className='primary-btn';spin.textContent='Quay chủ đề tiếp theo →';spin.addEventListener('click',()=>{showScreen('dashboardView');document.getElementById('dashboardView').classList.remove('hidden');renderDashboard();document.getElementById('wheelStatus').textContent='Bạn đã sẵn sàng cho chủ đề tiếp theo!';window.scrollTo({top:0,behavior:'smooth'})});retryActions.appendChild(spin)}const sum=document.getElementById('resultSummary');sum.innerHTML=`<div class="mini-tile"><span>Chủ đề</span><b style="font-size:1rem">${escapeHtml(topic.name)}</b></div><div class="mini-tile"><span>Chế độ</span><b style="font-size:1rem">${result.mode==='retry'?'Luyện lại':'Ôn tập'}</b></div><div class="mini-tile"><span>Đã chọn đáp án</span><b>${result.answered}/${result.total}</b></div><div class="mini-tile"><span>Thời lượng</span><b>${fmt((Date.now()-(currentQuiz?.startedAt||Date.now()))/60000,1)} phút</b></div>`}
document.getElementById('resultDashboardBtn').addEventListener('click',()=>{currentQuiz=null;showScreen('dashboardView');document.getElementById('dashboardView').classList.remove('hidden');renderDashboard();window.scrollTo({top:0,behavior:'smooth'})});

